    """
    # Check if Gemfile exists first, as bundle list will fail or behave unexpectedly without it
    if not os.path.exists('Gemfile'):
        return False
    try:
        installed = subprocess.check_output(['bundle', 'list'])
    except OSError:
        return False
    return name in installed
