from django import template

from adhocracy4.modules.models import Module
from adhocracy4.phases.models import Phase
from meinberlin.apps.offlineevents.models import OfflineEvent

register = template.Library()


@register.assignment_tag
def offlineevents_and_modules_sorted(project):
    modules = list(project.module_set.all())
    events = list(OfflineEvent.objects.filter(project=project))
    res = modules + events

    def get_sort_key(item):
        if isinstance(item, Module):
            start_date = item.first_phase_start_date
            if start_date is None:
                # Sort modules without start dates to the future (end of list)
                return (1, item.pk)
            return (0, start_date)
        else:
            # OfflineEvent
            return (0, item.date)

    res_sorted = sorted(res, key=get_sort_key)
    return res_sorted


@register.filter
def is_phase(obj):
    return isinstance(obj, Phase)


@register.filter
def is_module(obj):
    return isinstance(obj, Module)


@register.filter
def is_offlineevent(obj):
    return isinstance(obj, OfflineEvent)
