        if 'Authorization' not in self.config or not self.config['Authorization']:
            raise ValueError("Missing or empty 'Authorization' credential in config.")
        if 'Content-Type' not in self.config or not self.config['Content-Type']:
            raise ValueError("Missing or empty 'Content-Type' credential in config.")

        headers = {}
        headers['Authorization'] = self.config['Authorization']
        headers['Content-Type'] = self.config['Content-Type']
        return headers

    def _perform_request(self, path, method, data=None, requires_auth=False):
        url = API_URL + path

        if method == "GET":
            if requires_auth:
                headers = self._get_auth_headers()
            else:
                headers = {}
            response = requests.get(url, headers=headers)
        elif method == 'POST':
            headers = self._get_auth_headers()
            response = requests.post(url, headers=headers)
        elif method == 'PUT':
            headers = self._get_auth_headers()
            response = requests.put(url, data=data, headers=headers)

        return response
