```python
#!/usr/bin/env python

# Indents a CAF log with trace verbosity. The script does *not* deal with a log
# with multiple threads.

# usage (read file): indent_trace_log.py FILENAME
#      (read stdin): indent_trace_log.py -
#      (filter): indent_trace_log.py --filter PATTERN FILENAME

import sys
import os
import fileinput
import re

def read_lines(fp, filter_pattern=None):
    indent = ""
    for line in fp:
        if filter_pattern:
            if not re.search(filter_pattern, line):
                continue
        if 'TRACE' in line and 'EXIT' in line:
            indent = indent[:-2]
        sys.stdout.write(indent)
        sys.stdout.write(line)
        if 'TRACE' in line and 'ENTRY' in line:
            indent += "  "

def main():
    args = sys.argv[1:]
    filter_pattern = None
    filepath = None

    i = 0
    while i < len(args):
        if args[i] == '--filter':
            if i + 1 < len(args):
                filter_pattern = args[i + 1]
                i += 2
            else:
                print("Error: --filter requires a pattern argument", file=sys.stderr)
                sys.exit(1)
        else:
            filepath = args[i]
            i += 1

    if not filepath:
        print("Error: No filename provided", file=sys.stderr)
        sys.exit(1)

    if filepath == '-':
        read_lines(fileinput.input(), filter_pattern)
    else:
        if not os.path.isfile(filepath):
            sys.exit()
        with open(filepath) as fp:
            read_lines(fp, filter_pattern)

if __name__ == "__main__":
    main()
```

