            'reply_text': 'Your message is important to us.',
        })
        try:
            yield helper.start_application()
            yield helper.send_message()
            [reply] = yield helper.get_dispatched_messages()
            assert reply['content'] == 'Your message is important to us.'
            assert reply['session_event'] == u'close'
        finally:
            yield helper.stop_application()

    @inlineCallbacks
    def test_receive_message_no_reply(self):
        helper = ProxyApplicationHelper(StaticReplyApplication, config={})
        try:
            yield helper.start_application()
            yield helper.send_message()
            assert (yield helper.get_dispatched_messages()) == []
        finally:
            yield helper.stop_application()
