def signup():
  form = SignupForm()

  if request.method == "POST":
    if form.validate() == False:
      return render_template('signup.html', form=form)
    else:
      new_user = form.save()
      db.session.add(new_user)
      db.session.commit()
      return "Success!"

  elif request.method == "GET":
    return render_template('signup.html', form=form)

if __name__ == "__main__":
  app.run(debug=True)
