    # Parse arguments to ensure they are not ignored
    bits = token.split_contents()
    # Default values
    li_node = "coop_bootstrap/li_node.html"

    # Simple argument parsing: look for key=value pairs
    # Expected usage: {% navigation_bootstrap li_node="custom.html" %}
    if len(bits) > 1:
        for bit in bits[1:]:
            if '=' in bit:
                key, value = bit.split('=', 1)
                # Remove quotes if present
                if (value.startswith('"') and value.endswith('"')) or \
                   (value.startswith("'") and value.endswith("'")):
                    value = value[1:-1]
                if key == 'li_node':
                    li_node = value

    return NavigationAsNestedUlNode(li_node=li_node)
